def design(feats):
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float); n, p = X.shape
    ids = list(feats.ids); types = list(feats.types)
    labs = sorted(set(feats.stratum))
    S = np.ones((n, 1)) if len(labs) < 2 else np.column_stack([np.ones(n)] + [np.array([s == l for s in feats.stratum], float) for l in labs[1:]])
    R = np.corrcoef(X, rowvar=False); R = np.nan_to_num(R)
    def ll(Z):
        b = np.zeros(Z.shape[1])
        for _ in range(30):
            pr = 1 / (1 + np.exp(-np.clip(Z @ b, -30, 30)))
            H = Z.T @ (Z * (pr * (1 - pr))[:, None]) + 1e-6 * np.eye(Z.shape[1])
            st = np.linalg.solve(H, Z.T @ (y - pr)); b += st
            if np.abs(st).max() < 1e-7: break
        pr = np.clip(1 / (1 + np.exp(-Z @ b)), 1e-12, 1 - 1e-12)
        return float(np.sum(y * np.log(pr) + (1 - y) * np.log(1 - pr)))
    def col(t): return X[:, t[0]] * X[:, t[1]] if isinstance(t, tuple) else X[:, t]
    def mk(terms): return np.column_stack([S] + [col(t) for t in terms])
    deg = (np.abs(R) >= 0.6).sum(0) - 1
    hubs = [j for j in np.argsort(-deg) if types[j] == 'clinical' and deg[j] >= 3][:3]
    def gain(j, sel):
        base = list(sel) + [h for h in hubs if h != j and h not in sel]
        return 2 * (ll(mk(base + [j])) - ll(mk(base)))
    TW = 0.85
    sel = []; alphas = [0.01 / p, 0.01 / p, 0.01 / p]
    for k in range(6):
        a = alphas[min(k, 2)]
        cand = [j for j in range(p) if j not in sel and j not in hubs and all(abs(R[j, s]) < TW for s in sel)]
        if not cand: break
        g = [gain(j, sel) for j in cand]; b = int(np.argmax(g))
        if stats.chi2.sf(g[b], 1) > a: break
        j = cand[b]
        cl = [m for m in cand if abs(R[j, m]) >= 0.6]
        if len(cl) > 1:
            gm = {m: g[cand.index(m)] for m in cl}
            ok = [m for m in gm if gm[m] >= g[b] - 2]
            j = min(ok, key=lambda m: sum(gain(o, sel + [m]) for o in ok if o != m))
        sel.append(j)
    changed = True
    while changed and sel:
        changed = False
        for j in list(sel):
            if stats.chi2.sf(gain(j, [s for s in sel if s != j]), 1) > 0.01 / p:
                sel.remove(j); changed = True; break
    for h in hubs:
        C = [m for m in range(p) if (m == h or abs(R[h, m]) >= TW) and m not in sel and all(abs(R[m, s]) < TW for s in sel)]
        if h not in C: continue
        l0 = ll(mk(sel)); gs = {m: 2 * (ll(mk(sel + [m])) - l0) for m in C}
        m = max(gs, key=gs.get); m = m if gs[m] > gs[h] + 6 else h
        if stats.chi2.sf(gs[m], 1) < 0.01 / p: sel.append(m)
    sel.sort(key=lambda j: -gain(j, [s for s in sel if s != j]))
    prods = []
    base = sel + [h for h in hubs if h not in sel]
    pairs = [(i, j) for i in range(p) for j in range(i, p)]
    r0 = y - y.mean()
    sc = np.array([abs(np.dot(X[:, i] * X[:, j] - (X[:, i] * X[:, j]).mean(), r0)) / (np.std(X[:, i] * X[:, j]) + 1e-9) for i, j in pairs])
    thr = 0.005 / len(pairs)
    for idx in np.argsort(-sc)[:20]:
        i, j = pairs[idx]
        mains = list(dict.fromkeys(base + [i, j]))
        lm = ll(mk(mains)); lp = ll(mk(mains + [(i, j)]))
        if stats.chi2.sf(2 * (lp - lm), 1) < thr:
            if all(abs(R[i, a]) < 0.9 or abs(R[j, b]) < 0.9 for a, b in prods): prods.append((i, j))
        if len(prods) >= 2: break
    drivers = list(sel)
    for i, j in prods:
        for m in (i, j):
            if m not in drivers: drivers.append(m)
    if not drivers: return Design(drivers=(), columns=(), products=(), loadings={})
    cols = list(dict.fromkeys(sel + [m for pr_ in prods for m in pr_] + [h for h in hubs if h not in sel]))
    return Design(drivers=tuple(ids[m] for m in drivers[:MAX_DRIVERS]), columns=tuple(ids[m] for m in cols),
                  products=tuple((ids[i], ids[j]) for i, j in prods), loadings={})

